import { useState } from 'react'
import {
  ProFormRadio,
  ProFormDigit,
} from '@ant-design/pro-components'
import { Row, Col, Space, Tag, Button, Form } from 'antd'
import { PlusOutlined, CloseCircleOutlined } from '@ant-design/icons'
import {
  GOODS_STATUS_OPTIONS,
  PAY_NODE_OPTIONS,
  PAY_PARTY_OPTIONS,
  POINT_DEDUCT_OPTIONS,
} from '@/constants'
import { PlatformUserTypes } from '@/apis/admin/platform-user'
import MerchantSelectModal from './MerchantSelectModal'

interface BusinessSettingsSectionProps {
  /** 积分抵扣是否启用 */
  pointDeductEnabled: boolean
  /** 积分抵扣变化回调 */
  onPointDeductChange: (value: boolean) => void
  /** 选中的商户员 */
  selectedCouriers: PlatformUserTypes.MerchantUserListDto[]
  /** 配送员变化回调 */
  onSelectedCouriersChange: (couriers: PlatformUserTypes.MerchantUserListDto[]) => void
}

/**
 * 涓氬姟璁剧疆鍖哄潡缁勪欢 - 绱у噾甯冨眬
 * 鍚堝苟绉垎鎶垫墸璁剧疆鍜屽叾浠栬缃? */
const BusinessSettingsSection: React.FC<BusinessSettingsSectionProps> = ({
  pointDeductEnabled,
  onPointDeductChange,
  selectedCouriers,
  onSelectedCouriersChange,
}) => {
  const [modalVisible, setModalVisible] = useState(false)
  const form = Form.useFormInstance()

  // 打开弹窗
  const handleOpenModal = () => {
    setModalVisible(true)
  }

  // 关闭弹窗
  const handleCancel = () => {
    setModalVisible(false)
  }

  // 确认选择
  const handleConfirm = (rows: PlatformUserTypes.MerchantUserListDto[]) => {
    onSelectedCouriersChange(rows)
    // 更新表单值
    form?.setFieldsValue({
      merchantId: rows.map(item => item.id),
    })
    setModalVisible(false)
  }

  // 移除选中的商户员
  const handleRemove = (id: number) => {
    const newSelected = selectedCouriers.filter(item => item.id !== id)
    onSelectedCouriersChange(newSelected)
    form?.setFieldsValue({
      merchantId: newSelected.map(item => item.id),
    })
  }

  return (
    <>
      <Space direction="vertical" style={{ display: 'flex' }} size={0}>
        {/* 第一行：积分抵扣、抵扣比例（如果启用） */}
        <Row gutter={24}>
          <Col xs={24} sm={12}>
            <ProFormRadio.Group
              name="pointDeduct"
              label="积分抵扣"
              rules={[{ required: true, message: '请选择' }]}
              options={POINT_DEDUCT_OPTIONS}
              fieldProps={{
                onChange: (e) => onPointDeductChange(e.target.value === 1)
              }}
            />
          </Col>
          {pointDeductEnabled && (
            <Col xs={24} sm={12}>
            <ProFormDigit
                name="pointDeductLimit"
                label="抵扣比例"
                placeholder="请输入比例"
                rules={[
                  { required: pointDeductEnabled, message: '请输入' },
                  { type: 'number', min: 0, max: 100, message: '0-100之间' }
                ]}
                min={0}
                max={100}
                precision={0}
                fieldProps={{ addonAfter: '%' }}
                tooltip="单笔订单最多可抵扣订单金额的百分比"
              />
            </Col>
          )}
          {!pointDeductEnabled && (
            <Col xs={24} sm={12}>
              <ProFormRadio.Group
                name="goodsStatus"
                label="商品状态"
                rules={[{ required: true, message: '请选择' }]}
                options={GOODS_STATUS_OPTIONS.map(opt => ({
                  label: opt.color ? (
                    <Tag color={opt.color as any}>{opt.label}</Tag>
                  ) : opt.label,
                  value: opt.value,
                }))}
              />
            </Col>
          )}
        </Row>

        {/* 第二行：商品状态、支付节点 */}
        <Row gutter={24}>
          {pointDeductEnabled && (
            <Col xs={24} sm={12}>
              <ProFormRadio.Group
                name="goodsStatus"
                label="商品状态"
                rules={[{ required: true, message: '请选择' }]}
                options={GOODS_STATUS_OPTIONS.map(opt => ({
                  label: opt.color ? (
                    <Tag color={opt.color as any}>{opt.label}</Tag>
                  ) : opt.label,
                  value: opt.value,
                }))}
              />
            </Col>
          )}
          <Col xs={24} sm={12}>
            <ProFormRadio.Group
              name="payNode"
              label="支付节点"
              rules={[{ required: true, message: '请选择' }]}
              options={PAY_NODE_OPTIONS}
              tooltip="存件=存放时支付，取件=取出时支付"
            />
          </Col>
          {!pointDeductEnabled && (
            <Col xs={24} sm={12}>
              <ProFormRadio.Group
                name="payParty"
                 label="支付方"
                rules={[{ required: true, message: '请选择' }]}
                options={PAY_PARTY_OPTIONS}
                tooltip="用户端=用户支付，配送端=配送员支付，无=免费"
              />
            </Col>
          )}
        </Row>

         {/* 第三行：支付方、配送员关联 */}
        <Row gutter={24}>
          {pointDeductEnabled && (
            <Col xs={24} sm={12}>
              <ProFormRadio.Group
                name="payParty"
                label="支付方"
                rules={[{ required: true, message: '请选择' }]}
                options={PAY_PARTY_OPTIONS}
                tooltip="用户端=用户支付，配送端=配送员支付，无=免费"
              />
            </Col>
          )}
          <Col xs={24} sm={12}>
            <Form.Item
              name="merchantId"
               label="商户关联"
              tooltip="选中的商户才能在配送端看到此商品"
            >
              <div>
                {/* 已选商户标签 */}
                <div style={{ marginBottom: 8, minHeight: 32 }}>
                  {selectedCouriers.length > 0 ? (
                    <Space size={[8, 8]} wrap>
                      {selectedCouriers.map(item => (
                        <Tag
                          key={item.id}
                          color="blue"
                          closable
                          onClose={() => handleRemove(item.id)}
                          closeIcon={<CloseCircleOutlined />}
                        >
                          {item.merchantName} ({item.contactPhone})
                        </Tag>
                      ))}
                    </Space>
                  ) : (
                    <span style={{ color: '#999', fontSize: 14 }}>请选择商户</span>
                  )}
                </div>
                {/* 选择按钮 */}
                <Button
                  type="dashed"
                  icon={<PlusOutlined />}
                  onClick={handleOpenModal}
                  size="small"
                >
                 选择商户
                </Button>
              </div>
            </Form.Item>
          </Col>
        </Row>
      </Space>

      {/* 商户选择弹窗 */}
      <MerchantSelectModal
        visible={modalVisible}
        onCancel={handleCancel}
        onConfirm={handleConfirm}
        initialSelectedIds={selectedCouriers.map(item => item.id)}
      />
    </>
  )
}

export default BusinessSettingsSection

