import { useState } from 'react'
import { Upload, Image, Form, message } from 'antd'
import { InboxOutlined, InfoCircleOutlined } from '@ant-design/icons'
import type { UploadFile, UploadProps } from 'antd/es/upload'
import { uploadImage } from '@/apis/admin/site'
import { ResultEnum } from '@/utils/enums/httpEnum'

interface ImageUploadProps {
  /** 图片列表 */
  fileList: UploadFile[]
  /** 图片列表变化回调 */
  onChange: (fileList: UploadFile[]) => void
  /** 最大数量 */
  maxCount?: number
}

/**
 * 图片上传组件
 */
const ImageUpload: React.FC<ImageUploadProps> = ({
  fileList,
  onChange,
  maxCount = 5,
}) => {
  const [previewImage, setPreviewImage] = useState('')
  const [previewOpen, setPreviewOpen] = useState(false)

  const allowedTypes = ['image/jpeg', 'image/png', 'image/jpg', 'image/gif']
  const maxFileSizeMB = 2

  // 处理图片列表变化
  const handleChange: UploadProps['onChange'] = ({ fileList: newFileList }) => {
    const normalizedFileList = newFileList
      .map((file) => {
        const response = file.response as string | { url?: string } | undefined
        const responseUrl = typeof response === 'string' ? response : response?.url
        const nextUrl = file.url || responseUrl
        return nextUrl ? { ...file, url: nextUrl } : file
      })
      .filter((file) => {
        const rawFile = file.originFileObj
        if (!(rawFile instanceof File)) {
          return true
        }

        const isAllowedType = allowedTypes.includes(rawFile.type)
        const isLt2M = rawFile.size / 1024 / 1024 < maxFileSizeMB
        return isAllowedType && isLt2M
      })

    onChange(normalizedFileList)
  }

  // 处理图片预览
  const handlePreview = async (file: UploadFile) => {
    if (!file.url && !file.preview && file.originFileObj instanceof File) {
      file.preview = await getBase64(file.originFileObj)
    }

    const nextPreviewImage = file.url || (file.preview as string)
    if (!nextPreviewImage) {
      message.error('当前图片无法预览')
      return
    }

    setPreviewImage(nextPreviewImage)
    setPreviewOpen(true)
  }

  // 获取图片 base64
  const getBase64 = (file: File): Promise<string> =>
    new Promise((resolve, reject) => {
      const reader = new FileReader()
      reader.readAsDataURL(file)
      reader.onload = () => resolve(reader.result as string)
      reader.onerror = (error) => reject(error)
    })

  // 上传前校验
  const beforeUpload = (file: File) => {
    const isAllowedType = allowedTypes.includes(file.type)
    if (!isAllowedType) {
      message.error('只支持 JPG/PNG/GIF 格式的图片')
      return Upload.LIST_IGNORE
    }

    const isLt2M = file.size / 1024 / 1024 < maxFileSizeMB
    if (!isLt2M) {
      message.error('图片大小不能超过 2MB!')
      return Upload.LIST_IGNORE
    }

    return true
  }

  // 上传按钮
  const uploadButton = (
    <div>
      <InboxOutlined style={{ fontSize: 24, color: '#999' }} />
      <div style={{ marginTop: 8, color: '#666', fontSize: 12 }}>点击上传</div>
      <div style={{ color: '#999', fontSize: 11 }}>支持拖拽</div>
    </div>
  )

  return (
    <>
      <Form.Item name="goodsImages">
        <div>
          <Upload
            listType="picture-card"
            fileList={fileList}
            onPreview={handlePreview}
            onChange={handleChange}
            beforeUpload={beforeUpload}
            maxCount={maxCount}
            accept="image/jpeg,image/jpg,image/png,image/gif"
            customRequest={async ({ file, onSuccess, onError }) => {
              try {
                const formData = new FormData()
                formData.append('file', file)
                formData.append('bizType', 'goods')
                const res = await uploadImage(formData)
                if (res.code === ResultEnum.SUCCESS && res.data?.url) {
                  onSuccess?.({ url: res.data.url })
                } else {
                  onError?.(new Error(res.message || '上传失败'))
                  message.error(res.message || '上传失败')
                }
              } catch (error) {
                onError?.(error as Error)
                message.error('上传失败')
              }
            }}
          >
            {fileList.length >= maxCount ? null : uploadButton}
          </Upload>
          <div style={{ fontSize: 12, color: '#999', marginTop: 8 }}>
            <InfoCircleOutlined style={{ marginRight: 4 }} />
            最多{maxCount}张，单张不超过2MB，支持jpg/png/gif格式
          </div>
        </div>
      </Form.Item>

      {/* 图片预览 */}
      {previewImage && (
        <Image
          wrapperStyle={{ display: 'none' }}
          preview={{
            visible: previewOpen,
            onVisibleChange: (visible) => setPreviewOpen(visible),
            afterOpenChange: (visible) => !visible && setPreviewImage(''),
          }}
          src={previewImage}
        />
      )}
    </>
  )
}

export default ImageUpload
