import { useEffect, useState } from 'react'
import { Modal, Table, Input, Button, Space, Tag } from 'antd'
import { SearchOutlined } from '@ant-design/icons'
import { getMerchantUserList, PlatformUserTypes } from '@/apis/admin/platform-user'
import { ResultEnum } from '@/utils/enums/httpEnum'

interface CourierSelectModalProps {
  visible: boolean
  onCancel: () => void
  onConfirm: (selectedRows: PlatformUserTypes.MerchantUserListDto[]) => void
  initialSelectedIds?: number[]
}

const MerchantSelectModal: React.FC<CourierSelectModalProps> = ({
  visible,
  onCancel,
  onConfirm,
  initialSelectedIds = []
}) => {
  const [loading, setLoading] = useState(false)
  const [dataSource, setDataSource] = useState<PlatformUserTypes.MerchantUserListDto[]>([])
  const [selectedRowKeys, setSelectedRowKeys] = useState<number[]>(initialSelectedIds)
  const [selectedRows, setSelectedRows] = useState<PlatformUserTypes.MerchantUserListDto[]>([])
  const [searchPhone, setSearchPhone] = useState('')
  const [searchMerchantName, setSearchMerchantName] = useState('')
  const [pagination, setPagination] = useState({
    current: 1,
    pageSize: 10,
    total: 0
  })

  const loadData = async (page = 1, contactPhone?: string, merchantName?: string) => {
    try {
      setLoading(true)
      const res = await getMerchantUserList({
        page,
        pageSize: 10,
        status: 1,
        contactPhone,
        merchantName
      })
      if (res.code === ResultEnum.SUCCESS && res.data) {
        setDataSource(res.data.list)
        setPagination({
          current: res.data.page,
          pageSize: res.data.pageSize,
          total: res.data.totalCount
        })
      }
    } catch (e) {
      console.error('获取商户列表失败:', e)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (visible) {
      loadData(1)
      setSelectedRowKeys(initialSelectedIds)
    }
  }, [visible])

  const handleSearch = () => {
    loadData(1, searchPhone || undefined, searchMerchantName || undefined)
  }

  const handleReset = () => {
    setSearchPhone('')
    setSearchMerchantName('')
    loadData(1)
  }

  const handlePageChange = (page: number) => {
    loadData(page, searchPhone || undefined, searchMerchantName || undefined)
  }

  const handleConfirm = () => {
    onConfirm(selectedRows)
  }

  const columns = [
    {
      title: '商户名称',
      dataIndex: 'merchantName',
      key: 'merchantName',
      width: 150
    },
    {
      title: '联系电话',
      dataIndex: 'contactPhone',
      key: 'contactPhone',
      width: 140
    },
    {
      title: '联系人',
      dataIndex: 'contactUser',
      key: 'contactUser',
      width: 120,
      render: (contactUser: string) => contactUser || '-'
    },
    {
      title: '设备绑定数',
      dataIndex: 'bindDeviceNum',
      key: 'bindDeviceNum',
      width: 110,
      render: (bindDeviceNum: number) => bindDeviceNum || 0
    },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      width: 80,
      render: (status: number) => (
        <Tag color={status === 1 ? 'success' : 'error'}>{status === 1 ? '正常' : '禁用'}</Tag>
      )
    }
  ]

  const rowSelection = {
    selectedRowKeys,
    onChange: (keys: React.Key[], rows: PlatformUserTypes.MerchantUserListDto[]) => {
      setSelectedRowKeys(keys as number[])
      setSelectedRows(rows)
    }
  }

  return (
    <Modal
      title="选择商户"
      open={visible}
      onCancel={onCancel}
      width={800}
      footer={
        <Space>
          <Button onClick={onCancel}>取消</Button>
          <Button type="primary" onClick={handleConfirm}>
            确定 ({selectedRowKeys.length})
          </Button>
        </Space>
      }
    >
      <Space style={{ marginBottom: 16 }}>
        <Input
          placeholder="请输入联系电话"
          value={searchPhone}
          onChange={e => setSearchPhone(e.target.value)}
          onPressEnter={handleSearch}
          style={{ width: 150 }}
          allowClear
        />
        <Input
          placeholder="请输入商户名称"
          value={searchMerchantName}
          onChange={e => setSearchMerchantName(e.target.value)}
          onPressEnter={handleSearch}
          style={{ width: 150 }}
          allowClear
        />
        <Button type="primary" icon={<SearchOutlined />} onClick={handleSearch}>
          搜索
        </Button>
        <Button onClick={handleReset}>重置</Button>
      </Space>

      <Table
        rowKey="id"
        columns={columns}
        dataSource={dataSource}
        loading={loading}
        rowSelection={{
          type: 'checkbox',
          ...rowSelection
        }}
        pagination={{
          ...pagination,
          onChange: handlePageChange,
          showSizeChanger: false,
          showTotal: total => `共 ${total} 条`
        }}
        size="small"
        scroll={{ y: 400 }}
      />
    </Modal>
  )
}

export default MerchantSelectModal

