import { useEffect, useRef, useState } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { PageContainer, ProCard, ProForm, ProFormInstance } from '@ant-design/pro-components'
import { Button, message, Space, Tag, Divider } from 'antd'
import {
  ArrowLeftOutlined,
  SaveOutlined,
  CloseOutlined,
  InfoCircleOutlined,
  AppstoreOutlined,
  SettingOutlined
} from '@ant-design/icons'
import { getGoodsDetail, addGoods, editGoods, GoodsTypes } from '@/apis/admin/goods'
import { getServiceTypeList, SystemConfigTypes } from '@/apis/admin/system-config'
import { PlatformUserTypes, getMerchantUserList } from '@/apis/admin/platform-user'
import { ResultEnum } from '@/utils/enums/httpEnum'
import type { UploadFile } from 'antd/es/upload'
import {
  BasicInfoSection,
  SpecPriceSection,
  BusinessSettingsSection
} from './components/ProductEdit'

const ProductEdit: React.FC = () => {
  const navigate = useNavigate()
  const { id } = useParams<{ id: string }>()
  const formRef = useRef<ProFormInstance>()

  const goodsId = Number(id) || 0
  const isEditMode = goodsId > 0

  const [loading, setLoading] = useState(false)
  const [serviceTypeList, setServiceTypeList] = useState<SystemConfigTypes.ServiceTypeListDto[]>([])
  const [selectedCouriers, setSelectedCouriers] = useState<PlatformUserTypes.MerchantUserListDto[]>([])
  const [fileList, setFileList] = useState<UploadFile[]>([])
  const [pointDeductEnabled, setPointDeductEnabled] = useState(true)

  // 加载服务类型列表（仅启用的）
  const loadServiceTypeList = async () => {
    try {
      const res = await getServiceTypeList({ status: 1, pageSize: 100 })
      if (res.code === ResultEnum.SUCCESS && res.data?.list) {
        setServiceTypeList(res.data.list)
      }
    } catch (e) {
      console.error('获取服务类型列表失败:', e)
    }
  }

  // 获取商品详情（编辑模式）
  const fetchGoodsDetail = async () => {
    if (!isEditMode) {
      return
    }
    try {
      setLoading(true)
      const res = await getGoodsDetail(goodsId)
      if (res.code === ResultEnum.SUCCESS && res.data) {
        const data = res.data
        formRef.current?.setFieldsValue({
          goodsName: data.goodsName,
          gridSpec: data.gridSpec,
          serviceTypeId: data.serviceTypeId,
          costPrice: data.costPrice,
          initialPrice: data.initialPrice,
          overtimePrice: data.overtimePrice,
          freeDays: data.freeDays,
          pointDeduct: data.pointDeduct,
          pointDeductLimit: data.pointDeductLimit,
          goodsStatus: data.goodsStatus,
          payNode: data.payNode,
          payParty: data.payParty,
          merchantId: data.merchantId || []
        })

        setPointDeductEnabled(data.pointDeduct === 1)

        // 设置图片
        if (data.goodsImages && data.goodsImages.length > 0) {
          const images = data.goodsImages.map((url, index) => ({
            uid: `-${index}`,
            name: `image-${index}.jpg`,
            status: 'done' as const,
            url
          }))
          setFileList(images)
        }
        const merchantIds = data.merchantId || []
        if (merchantIds.length > 0) {
          const merchantRes = await getMerchantUserList({
            page: 1,
            pageSize: Math.max(merchantIds.length, 100)
          })
          if (merchantRes.code === ResultEnum.SUCCESS && merchantRes.data?.list) {
            setSelectedCouriers(merchantRes.data.list.filter(item => merchantIds.includes(item.id)))
          } else {
            setSelectedCouriers([])
          }
        } else {
          setSelectedCouriers([])
        }
      }
    } catch (e) {
      console.error('获取商品详情失败:', e)
      message.error('获取商品详情失败')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadServiceTypeList()
    if (isEditMode) {
      fetchGoodsDetail()
    }
  }, [isEditMode])

  // 提交表单
  const handleSubmit = async () => {
    const values = await formRef.current?.validateFields()
    if (!values) {
      return
    }

    try {
      setLoading(true)

      // 处理图片列表
      const goodsImages = fileList
        .filter(file => file.status === 'done')
        .map(file => file.url || file.response?.url || file.thumbUrl)
        .filter(Boolean) as string[]

      const selectedServiceType = serviceTypeList.find(item => item.id === values.serviceTypeId)

      const data: GoodsTypes.AddGoodsReq = {
        goodsName: values.goodsName,
        gridSpec: values.gridSpec,
        serviceTypeId: values.serviceTypeId,
        serviceTypeName: selectedServiceType?.name || '',
        costPrice: Number(values.costPrice),
        initialPrice: Number(values.initialPrice),
        overtimePrice: Number(values.overtimePrice),
        freeDays: Number(values.freeDays),
        merchantId: values.merchantId || [],
        pointDeduct: values.pointDeduct,
        pointDeductLimit: values.pointDeduct === 1 ? Number(values.pointDeductLimit) : 0,
        goodsStatus: values.goodsStatus,
        payNode: values.payNode,
        payParty: values.payParty,
        goodsImages
      }

      let res
      if (isEditMode) {
        const editData: GoodsTypes.EditGoodsReq = data
        res = await editGoods(goodsId, editData)
      } else {
        res = await addGoods(data)
      }

      if (res.code === ResultEnum.SUCCESS) {
        message.success(isEditMode ? '商品修改成功' : '商品添加成功')
        navigate('/product/list')
      } else {
        message.error(res.message || '操作失败')
      }
    } catch (e) {
      console.error('提交失败:', e)
      message.error('操作失败')
    } finally {
      setLoading(false)
    }
  }

  const handlePointDeductChange = (value: boolean) => {
    setPointDeductEnabled(value)
  }

  // 处理商户选择变化
  const handleSelectedCouriersChange = (couriers: PlatformUserTypes.MerchantUserListDto[]) => {
    setSelectedCouriers(couriers)
  }

  return (
    <PageContainer
      header={{
        title: (
          <Space>
            <Button
              type="text"
              icon={<ArrowLeftOutlined />}
              onClick={() => navigate('/product/list')}
            >
              返回商品列表
            </Button>
            {isEditMode && (
              <Tag color="orange" icon={<InfoCircleOutlined />}>
                编辑模式
              </Tag>
            )}
          </Space>
        ),
        breadcrumb: undefined
      }}
    >
      <ProForm
        formRef={formRef}
        submitter={false}
        layout="horizontal"
        labelCol={{ flex: '0 0 100px' }}
        wrapperCol={{ flex: '1 1 auto' }}
        labelAlign="right"
        loading={loading}
        initialValues={{
          gridSpec: 1,
          goodsStatus: 1,
          payNode: 1,
          payParty: 1,
          pointDeduct: 1,
          pointDeductLimit: 100,
          freeDays: 0,
          merchantId: []
        }}
      >
        {/* 区块1: 基本信息 + 规格价格 */}
        <ProCard
          title={
            <span>
              <AppstoreOutlined style={{ color: '#1890ff', marginRight: 8 }} />
              商品信息
            </span>
          }
          bordered
          style={{ marginBottom: 16 }}
          bodyStyle={{ paddingBottom: 8 }}
        >
          <BasicInfoSection fileList={fileList} onFileListChange={setFileList} />

          <Divider style={{ margin: '16px 0' }} />

          <SpecPriceSection serviceTypeList={serviceTypeList} />
        </ProCard>

        {/* 区块2: 业务设置（积分抵扣 + 其他设置） */}
        <ProCard
          title={
            <span>
              <SettingOutlined style={{ color: '#1890ff', marginRight: 8 }} />
              业务设置
            </span>
          }
          bordered
          style={{ marginBottom: 16 }}
          bodyStyle={{ paddingBottom: 8 }}
        >
          <BusinessSettingsSection
            pointDeductEnabled={pointDeductEnabled}
            onPointDeductChange={handlePointDeductChange}
            selectedCouriers={selectedCouriers}
            onSelectedCouriersChange={handleSelectedCouriersChange}
          />
        </ProCard>

        {/* 提交按钮 */}
        <div style={{ display: 'flex', gap: 12, justifyContent: 'center', padding: '16px 0' }}>
          <Button
            type="primary"
            icon={<SaveOutlined />}
            size="large"
            onClick={handleSubmit}
            loading={loading}
          >
            {isEditMode ? '保存修改' : '提交上架'}
          </Button>
          <Button icon={<CloseOutlined />} size="large" onClick={() => navigate('/product/list')}>
            取消
          </Button>
        </div>
      </ProForm>
    </PageContainer>
  )
}

export default ProductEdit
