import {
  ProFormRadio,
  ProFormSelect,
  ProFormDigit,
} from '@ant-design/pro-components'
import { Row, Col, Space } from 'antd'
import { SystemConfigTypes } from '@/apis/admin/system-config'
import { useDeviceCabinetSpec } from '@/hooks/useDeviceCabinetSpec'

interface SpecPriceSectionProps {
  /** 服务类型列表 */
  serviceTypeList: SystemConfigTypes.ServiceTypeListDto[]
}

/**
 * 规格与价格区块组件 - 紧凑布局
 */
const SpecPriceSection: React.FC<SpecPriceSectionProps> = ({
  serviceTypeList
}) => {
  // 使用动态获取的格口规格
  const { gridSpecOptions, loading: specLoading } = useDeviceCabinetSpec()
  return (
    <Space direction="vertical" style={{ display: 'flex' }} size={0}>
      {/* 第一行：格口规格、服务类型 */}
      <Row gutter={24}>
        <Col xs={24} sm={12}>
          <ProFormRadio.Group
            name="gridSpec"
            label="格口规格"
            rules={[{ required: true, message: '请选择格口规格' }]}
            options={gridSpecOptions}
            disabled={specLoading}
          />
        </Col>
        <Col xs={24} sm={12}>
          <ProFormSelect
            name="serviceTypeId"
            label="服务类型"
            placeholder="请选择服务类型"
            rules={[{ required: true, message: '请选择服务类型' }]}
            options={serviceTypeList.map(item => ({
              label: item.name,
              value: item.id,
            }))}
            fieldProps={{ showSearch: true }}
          />
        </Col>
      </Row>

      {/* 第二行：成本价、初始价格 */}
      <Row gutter={24}>
        <Col xs={24} sm={12}>
          <ProFormDigit
            name="costPrice"
            label="成本价"
            placeholder="请输入成本价"
            rules={[{ required: true, message: '请输入成本价' }]}
            min={0}
            precision={2}
            fieldProps={{ addonAfter: '元' }}
          />
        </Col>
        <Col xs={24} sm={12}>
          <ProFormDigit
            name="initialPrice"
            label="初始价格"
            placeholder="请输入初始价格"
            rules={[{ required: true, message: '请输入初始价格' }]}
            min={0}
            precision={2}
            fieldProps={{ addonAfter: '元' }}
          />
        </Col>
      </Row>

      {/* 第三行：超时价格、免费天数 */}
      <Row gutter={24}>
        <Col xs={24} sm={12}>
          <ProFormDigit
            name="overtimePrice"
            label="超时价格"
            placeholder="请输入超时价格"
            rules={[{ required: true, message: '请输入超时价格' }]}
            min={0}
            precision={2}
            fieldProps={{ addonAfter: '元/天' }}
          />
        </Col>
        <Col xs={24} sm={12}>
          <ProFormDigit
            name="freeDays"
            label="免费天数"
            placeholder="请输入免费天数"
            rules={[{ required: true, message: '请输入免费天数' }]}
            min={0}
            precision={0}
            fieldProps={{ addonAfter: '天' }}
          />
        </Col>
      </Row>

      {/* 价格公式提示 */}
      <div style={{
        fontSize: 12,
        color: '#8c8c8c',
        padding: '8px 12px',
        background: '#f6ffed',
        border: '1px solid #b7eb8f',
        borderRadius: 4,
        marginTop: 8,
        marginLeft: 100,
      }}>
        💡 售价 = 初始价格 + 超时价格 ×（超时天数 - 免费天数），超时天数 ≤ 免费天数时不收超时费
      </div>
    </Space>
  )
}

export default SpecPriceSection
